175	/* -----------------------------------------------------------
176	  Initialization
177	  Note: on some platforms lock_init or just a thread local access
178	  can cause allocation and induce recursion during initialization.
179	----------------------------------------------------------- */
180	
181	static mi_tld_t* mi_tld_init(mi_tld_t* tld, size_t tseq, mi_subproc_t* subproc);
182	
183	// Initialize main heap
184	static void mi_heap_main_init_once(void) {
185	  mi_memid_t memid_static = _mi_memid_create(MI_MEM_STATIC);
186	  _mi_memcpy(&_mi_theap_empty_wrong,&_mi_theap_empty,sizeof(_mi_theap_empty_wrong));
187	
188	  // initialize the main subprocess
189	  mi_subproc_t* subproc_main = _mi_subproc_main_init();
190	
191	  // detached tld for mi_theap_empty (and theap_meta)
192	  mi_tld_detached.memid = memid_static;
193	  mi_tld_init(&mi_tld_detached, 0, subproc_main);
194	
195	  // main process heap
196	  mi_process_heap_main.memid = memid_static;
197	  mi_atomic_store_ptr_release(mi_heap_t,&subproc_main->heap_main,&mi_process_heap_main);
198	  _mi_heap_init(&mi_process_heap_main,mi_thread_local_key_fast,subproc_main,0);
199	
200	  // detached theap for allocating meta-data (we can allocate on this without having an initialized thread)
201	  mi_process_theap_meta.memid = memid_static;
202	  _mi_theap_init(&mi_process_theap_meta,&mi_process_heap_main,&mi_tld_detached);
203	  mi_process_theap_meta.allow_page_abandon = false;  // for security, don't share with other threads
204	  mi_process_theap_meta.page_full_retain = 2;
205	  subproc_main->theap_meta = &mi_process_theap_meta;
206	
207	  // mi_heap_theap_set(&mi_process_heap_main,&mi_process_theap_main); // set in `mi_thread_init(_theap_default)`
208	}
209	
210	static void mi_heap_main_init(void) {
211	  mi_atomic_do_once {
212	    mi_heap_main_init_once();
213	  }
214	}
215	
216	mi_heap_t* _mi_subproc_heap_main(mi_subproc_t* subproc) {
217	  mi_heap_t* heap = mi_atomic_load_ptr_acquire(mi_heap_t,&subproc->heap_main);
218	  if mi_likely(heap!=NULL) {
219	    return heap;
220	  }
221	  else if (_mi_subproc_is_main(subproc)) {
222	    mi_heap_main_init();
223	    mi_assert_internal(mi_atomic_load_ptr_acquire(mi_heap_t,&subproc->heap_main) != NULL);
224	    return mi_atomic_load_ptr_acquire(mi_heap_t,&subproc->heap_main);
225	  }
226	  else {
227	    mi_assert_internal(false);
228	    return &mi_process_heap_main;
229	  }
230	}
