373	/* -----------------------------------------------------------
374	  Theaps done
375	----------------------------------------------------------- */
376	
377	// Free the thread local theaps
378	static void mi_thread_theaps_done(mi_tld_t* tld)
379	{
380	  // abandon the pages of all theaps in this thread
381	  mi_lock(&tld->theaps_lock) {
382	    mi_theap_t* theap = tld->theaps;
383	    while (theap != NULL) {
384	      mi_theap_t* next = theap->tnext;
385	      // never destroy theaps; if a dll is linked statically with mimalloc,
386	      // there may still be delete/free calls after the mi_fls_done is called. Issue #207
387	      _mi_theap_collect_abandon(theap);
388	      mi_assert_internal(theap->page_count==0);
389	      theap = next;
390	    }
391	  }
392	
393	  // reset the thread local theaps
394	  // note: do this after abandon as page->heap may be NULL and mi_heap_main should return the heap
395	  // belonging to the right subprocess
396	  _mi_theap_default_set((mi_theap_t*)&_mi_theap_empty);
397	  _mi_theap_cached_set((mi_theap_t*)&_mi_theap_empty);
398	
399	  // We might run concurrently with a `mi_heap_free_theaps` and we need to ensure we free theaps atomically.
400	  // we first detach our theaps list from any heaps
401	  _mi_tld_detach_theaps(tld);
402	
403	  // no heaps point to our theaps anymore, free them
404	  mi_lock(&tld->theaps_lock) { // paranoia
405	    mi_theap_t* theap = tld->theaps;
406	    tld->theaps = NULL;
407	    while (theap != NULL) {
408	      mi_theap_t* next = theap->tnext;
409	      mi_assert_internal(theap->page_count==0);
410	      mi_assert_internal(_mi_theap_heap_peek(theap)==NULL);
411	      theap->tld = NULL;
412	      theap->tnext = NULL;
413	      theap->tprev = NULL;
414	      mi_assert_internal(mi_atomic_load_relaxed(&theap->refcount) == 1); // as the cached entry is set to empty
415	      _mi_theap_decref(theap);
416	      theap = next;
417	    }
418	  }
419	
420	  mi_assert(_mi_theap_default()==(mi_theap_t*)&_mi_theap_empty); // careful to not re-initialize the default theap during theap_delete
421	  mi_assert(!mi_theap_is_initialized(_mi_theap_default()));
422	}
