424	
425	// --------------------------------------------------------
426	// Try to run `mi_thread_done()` automatically so any memory
427	// owned by the thread but not yet released can be abandoned
428	// and re-owned by another thread.
429	//
430	// 1. windows dynamic library:
431	//     call from DllMain on DLL_THREAD_DETACH
432	// 2. windows static library:
433	//     use special linker section to call a destructor when the thread is done
434	// 3. unix, pthreads:
435	//     use a pthread key to call a destructor when a pthread is done
436	//
437	// In the last two cases we also need to call `mi_process_init`
438	// to set up the thread local keys.
439	// --------------------------------------------------------
440	
441	// Set up hooks so `mi_thread_done` is called automatically
442	static void mi_process_setup_auto_thread_done(void) {
443	  mi_atomic_do_once {
444	    _mi_prim_thread_init_auto_done();
445	  }
446	}
447	
448	void mi_thread_done(void) mi_attr_noexcept {
449	  _mi_thread_done(NULL);
450	}
451	
452	void _mi_thread_done(mi_theap_t* _theap_main)
453	{
454	  // NULL can be passed on some platforms
455	  if (_theap_main==NULL) {
456	    _theap_main = _mi_theap_default();
457	  }
458	
459	  // prevent re-entrancy through theap_done/theap_set_default_direct (issue #699)
460	  if (!mi_theap_is_initialized(_theap_main)) {
461	    return;
462	  }
463	
464	  // get the current tld
465	  mi_tld_t* const tld = _theap_main->tld;
466	
467	  // release dynamic thread_local's
468	  _mi_thread_locals_thread_done();
469	
470	  // adjust stats
471	  mi_subproc_stat_decrease(tld->subproc, threads, 1);  // todo: or `_theap_main->heap`?
472	
473	  // check thread-id as on Windows shutdown with FLS the main (exit) thread may call this on thread-local theaps...
474	  if (tld->thread_id != _mi_prim_thread_id()) return;
475	
476	  // delete the thread local theaps
477	  mi_thread_theaps_done(tld);
478	
479	  // free thread local data
480	  mi_tld_free(tld);
481	}
