275	mi_decl_nodiscard long mi_option_get(mi_option_t option) {
276	  mi_assert(option >= 0 && option < _mi_option_last);
277	  if (option < 0 || option >= _mi_option_last) return 0;
278	  mi_option_desc_t* desc = &mi_options[option];
279	  mi_assert(desc->option == option);  // index should match the option
280	  if mi_unlikely(desc->init == MI_OPTION_UNINIT) {
