319	  mi_assert(option >= 0 && option < _mi_option_last);
320	  if (option < 0 || option >= _mi_option_last) return;
321	  mi_option_desc_t* desc = &mi_options[option];
322	  if (desc->init != MI_OPTION_INITIALIZED) {
